import java.util.ArrayList;

//Una nueva interfaz (Auditable)
public class LogisticaAvanzada extends ProveedorLogistica implements Auditable {
    //Este neccesita un Array de Eventos
	private ArrayList<Evento> eventos;

    public LogisticaAvanzada() {
        super();
        eventos = new ArrayList<Evento>();
    }


    public LogisticaAvanzada(String id, String nombre, int latencia, boolean listo, String configuracion, float tarifa) {
        super(id, nombre, latencia, listo, configuracion, tarifa);
        eventos = new ArrayList<Evento>();
    }


//Implementación del Envío
    @Override
    public void registrarEvento(Evento evento) {
		//Si el evento no está vacío
        if (evento != null) {
            eventos.add(evento);
        }
    }

    // Y Agregar Auditable

    @Override
    public ArrayList<Evento> consultarHistorialEventos() {

        return new ArrayList<Evento>(eventos);
    }
}
